#include <iostream>
#include <string>
#include <vector>

int main()
{
    std::vector<std::string> titles;
    titles.reserve(4);
    titles.push_back("Atlas");
    titles.push_back("Orbits");
    std::cout << titles.size() << ' ' << std::boolalpha
              << (titles.capacity() >= 4) << '\n';
    titles.erase(titles.begin());
    std::cout << titles.front() << ' ' << titles.size() << '\n';
}
